var channel = Channel.CreateBounded<EmailJob>(new BoundedChannelOptions(capacity: 100)
{
    FullMode = BoundedChannelFullMode.Wait,   // backpressure
    SingleReader = true,
});

// Producer (e.g. an endpoint):
await channel.Writer.WriteAsync(new EmailJob(userId), ct);

// Consumer (e.g. a BackgroundService):
await foreach (var job in channel.Reader.ReadAllAsync(stoppingToken))
{
    await SendAsync(job, stoppingToken);
}

// Shutdown: no more writes; readers drain what is left, then the loop ends.
channel.Writer.Complete();
